1	package retrieval
2	
3	import (
4		"sort"
5	
6		"github.com/entireio/entire-brain/factmerge"
7	)
8	
9	const (
10		CaveatStaleLocus              = "stale_locus"
11		CaveatCurrentCodeUnavailable  = "current_code_unavailable"
12		CaveatHistoricalDocument      = "historical_document"
13		CaveatHistoricalConversation  = "historical_conversation"
14		CaveatConversationSourceStale = "conversation_source_stale"
15		// Distinct expansion failure states: a too-large or unreadable
16		// source is not the same contract failure as a changed digest.
17		CaveatConversationSourceTooLarge   = "conversation_source_too_large"
18		CaveatConversationSourceUnreadable = "conversation_source_unreadable"
19	)
20	
21	// Caveat is a machine-readable reason an agent must verify a memory
22	// result against current evidence before relying on it.
23	type Caveat struct {
24		Kind       string   `json:"kind"`
25		Message    string   `json:"message"`
26		Paths      []string `json:"paths,omitempty"`
27		ReviewID   string   `json:"review_id,omitempty"`
28		Action     string   `json:"action,omitempty"`
29		Confidence float64  `json:"confidence,omitempty"`
30	}
31	
32	// AnnotateUnifiedFactResults annotates ranked fact results with current-code
33	// locus drift and enforces the caller's limit. (The pending-review collapse
34	// that used to live here left with the fact-proposal framework.)
35	func AnnotateUnifiedFactResults(repoDir string, facts []factmerge.Record, ranked []Result, limit int) []Result {
36		if limit <= 0 || len(ranked) == 0 {
37			return ranked
38		}
39		factByID := make(map[string]factmerge.Record, len(facts))
40		for _, fact := range facts {
41			factByID[fact.ID] = fact
42		}
43		out := make([]Result, 0, min(limit, len(ranked)))
44		for _, result := range ranked {
45			if result.Source == "fact" {
46				if fact, ok := factByID[result.ID]; ok {
47					out = append(out, AnnotateFactLocusTrust(repoDir, fact, result))
48				} else {
49					out = append(out, result)
50				}
51			} else {
52				out = append(out, result)
53			}
54			if len(out) >= limit {
55				break
56			}
57		}
58		return out
59	}
60	
61	func AnnotateCurrentCodeUnavailable(results []Result) []Result {
62		return annotateFactResultCaveat(results, Caveat{
63			Kind:    CaveatCurrentCodeUnavailable,
64			Message: "The repository worktree could not be safely resolved, so current-code locus verification was not performed.",
65		})
66	}
67	
68	func annotateFactResultCaveat(results []Result, caveat Caveat) []Result {
69		for i := range results {
70			if results[i].Source != "fact" {
71				continue
72			}
73			results[i].VerificationRequired = true
74			results[i].Caveats = append(results[i].Caveats, caveat)
75		}
76		return results
77	}
78	
79	func AnnotateFactLocusTrust(repoDir string, fact factmerge.Record, result Result) Result {
80		drift := FactLocusDrift(repoDir, fact)
81		if len(drift) == 0 {
82			return result
83		}
84		result.VerificationRequired = true
85		result.Caveats = append(result.Caveats, staleLocusCaveat(uniqueSortedStrings(drift)))
86		return result
87	}
88	
89	func staleLocusCaveat(paths []string) Caveat {
90		return Caveat{
91			Kind:    CaveatStaleLocus,
92			Message: "One or more referenced code files are absent from the current worktree; verify whether the fact was invalidated or moved.",
93			Paths:   paths,
94		}
95	}
96	
97	func sortedStringSet(values map[string]struct{}) []string {
98		out := make([]string, 0, len(values))
99		for value := range values {
100			out = append(out, value)
101		}
102		sort.Strings(out)
103		return out
104	}
105	
106	func uniqueSortedStrings(values []string) []string {
107		if len(values) == 0 {
108			return nil
109		}
110		sort.Strings(values)
111		out := values[:0]
112		for _, value := range values {
113			if len(out) == 0 || out[len(out)-1] != value {
114				out = append(out, value)
115			}
116		}
117		return out
118	}
119

