1	package factstore
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"time"
12	
13		"github.com/entireio/entire-brain/factmerge"
14		"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
15		bmanifest "github.com/entireio/entire-brain/internal/cli/internal/manifest"
16	)
17	
18	const (
19		DirName          = "facts"
20		TaxonomyFileName = "taxonomy.json"
21		TaxonomyPath     = DirName + "/" + TaxonomyFileName
22		FileName         = "facts.ndjson"
23		MaxPerChunk      = 6 // quality-gate output cap per source chunk
24	
25		OriginDistilled = "distilled"
26		OriginAuthored  = "authored"
27		OriginImported  = "imported"
28	)
29	
30	// factmerge.Record (factmerge.Record) and factmerge.Anchor (factmerge.Anchor) are defined
31	// as type aliases in facts_aliases.go; the durable-fact data model now lives in
32	// factmerge.
33	
34	// Taxonomy is the active taxonomy snapshot. Paths are validated against
35	// factPathPattern; classification may only invent a new three-level path under
36	// an existing top-level category.
37	type Taxonomy struct {
38		GeneratedAt time.Time         `json:"generated_at"`
39		Categories  map[string]string `json:"categories"` // top-level -> description
40		Paths       []PathDef         `json:"paths"`
41	}
42	
43	type PathDef struct {
44		Path        string   `json:"path"`
45		Description string   `json:"description"`
46		Examples    []string `json:"examples,omitempty"`
47	}
48	
49	// normalizeFactText, factRecordID, validFactPath, and normalizeFactPaths moved
50	// to factmerge (NormalizeText/RecordID/ValidPath/NormalizePaths); the
51	// CLI names are forwarding wrappers in facts_aliases.go.
52	
53	// TopLevel returns the top-level category of a taxonomy path (the segment
54	// before the first dot), or "" if the path is empty.
55	func TopLevel(path string) string {
56		if i := strings.IndexByte(path, '.'); i >= 0 {
57			return path[:i]
58		}
59		return path
60	}
61	
62	// --- on-disk layout -------------------------------------------------------
63	
64	// The flat store (facts/store.json) and its legacy-layout folding live in
65	// repo_fact_store.go and repo_fact_compat.go. Load and Write are defined
66	// there; branch is metadata on each record, never a storage key.
67	
68	// parseFactsFile reads a facts.ndjson file at an absolute path. A missing file
69	// yields an empty slice; a malformed line is a hard error so a corrupt store is
70	// surfaced rather than silently dropping records. The byte-level scan lives in
71	// factmerge.ParseNDJSON; this keeps only the file/path handling and restores the
72	// historical "parse <file> line N: ..." message the core cannot know the path
73	// for.
74	func parseFactsFile(path string) ([]factmerge.Record, error) {
75		f, err := os.Open(path)
76		if err != nil {
77			if os.IsNotExist(err) {
78				return nil, nil
79			}
80			return nil, err
81		}
82		defer f.Close()
83		records, err := factmerge.ParseNDJSON(f)
84		if err != nil {
85			var perr *factmerge.ParseError
86			if errors.As(err, &perr) {
87				return nil, fmt.Errorf("parse %s line %d: %w", filepath.Base(path), perr.Line, perr.Err)
88			}
89			return nil, err
90		}
91		return records, nil
92	}
93	
94	// --- taxonomy -------------------------------------------------------------
95	
96	// DefaultTaxonomy is the shipped baseline taxonomy. The top-level
97	// categories here are fixed in Phase A; distillation may invent a new
98	// three-level path only under one of these categories. The brain regenerates
99	// taxonomy.json from this default on refresh.
100	func DefaultTaxonomy(now time.Time) Taxonomy {
101		return Taxonomy{
102			GeneratedAt: now,
103			Categories: map[string]string{
104				"preferences":  "How the user wants to work and how code should be written.",
105				"architecture": "Resolved design, boundary, and data-flow decisions and their rationale.",
106				"project":      "Stack, tooling, CI/CD, ownership, and standing project facts.",
107				"workflow":     "Branching, testing, review, and release process rules.",
108				"constraints":  "Non-obvious invariants, gotchas, and hard constraints.",
109			},
110			Paths: []PathDef{
111				{Path: "preferences.coding.style", Description: "Stated code-style preferences.", Examples: []string{"prefers table-driven tests"}},
112				{Path: "preferences.workflow.general", Description: "How the user prefers to work day to day."},
113				{Path: "architecture.boundaries.rationale", Description: "Why a module or package boundary exists."},
114				{Path: "architecture.data.flow", Description: "How data moves through the system."},
115				{Path: "project.tooling.stack", Description: "Languages, frameworks, and tools the project uses."},
116				{Path: "project.ci_cd.pipeline", Description: "Build, test, and deploy pipeline facts."},
117				{Path: "workflow.branching.rules", Description: "Branching and merge conventions."},
118				{Path: "workflow.testing.rules", Description: "How and when tests must be run."},
119				{Path: "constraints.invariants.general", Description: "Invariants that must hold across changes."},
120			},
121		}
122	}
123	
124	// LoadTaxonomy reads the active taxonomy snapshot, falling back to the
125	// shipped default when the file is absent so callers always get a usable
126	// taxonomy. A present-but-malformed file is a hard error.
127	func LoadTaxonomy(brainDir string, now time.Time) (Taxonomy, error) {
128		path := filepath.Join(brainDir, filepath.FromSlash(TaxonomyPath))
129		data, err := os.ReadFile(path)
130		if err != nil {
131			if os.IsNotExist(err) {
132				return DefaultTaxonomy(now), nil
133			}
134			return Taxonomy{}, err
135		}
136		var taxonomy Taxonomy
137		if err := json.Unmarshal(data, &taxonomy); err != nil {
138			return Taxonomy{}, fmt.Errorf("parse %s: %w", TaxonomyPath, err)
139		}
140		return taxonomy, nil
141	}
142	
143	// WriteTaxonomy persists the active taxonomy snapshot.
144	func WriteTaxonomy(brainDir string, taxonomy Taxonomy) error {
145		data, err := json.MarshalIndent(taxonomy, "", "  ")
146		if err != nil {
147			return err
148		}
149		data = append(data, '\n')
150		return brainstore.WriteBrainRelativeFileAtomic(brainDir, TaxonomyPath, data, 0o600)
151	}
152	
153	// TaxonomyTopLevels returns the set of top-level categories the taxonomy
154	// recognizes. A fact whose path's top-level is absent from this set is an
155	// orphan (reported, never auto-deleted).
156	func TaxonomyTopLevels(taxonomy Taxonomy) map[string]struct{} {
157		tops := make(map[string]struct{}, len(taxonomy.Categories))
158		for category := range taxonomy.Categories {
159			tops[category] = struct{}{}
160		}
161		return tops
162	}
163	
164	// SortedTaxonomyTopLevels returns the taxonomy's top-level categories sorted
165	// alphabetically, for stable user-facing messages (e.g. rejecting an explicit
166	// --path under an unknown category).
167	func SortedTaxonomyTopLevels(taxonomy Taxonomy) []string {
168		cats := make([]string, 0, len(taxonomy.Categories))
169		for category := range taxonomy.Categories {
170			cats = append(cats, category)
171		}
172		sort.Strings(cats)
173		return cats
174	}
175	
176	// PathKnownTopLevel reports whether path's top-level category exists in the
177	// taxonomy. This is the conservative drift check: a fact keeps its assigned
178	// paths literally, and only its top-level category must still exist for it to
179	// remain valid.
180	func PathKnownTopLevel(taxonomy Taxonomy, path string) bool {
181		_, ok := TaxonomyTopLevels(taxonomy)[TopLevel(path)]
182		return ok
183	}
184	
185	// TaxonomyBlock renders the taxonomy as the prompt section the agent uses to
186	// classify facts: the fixed top-level categories and the known three-level
187	// paths with descriptions. Output is deterministic (sorted) so the rendered
188	// prompt is stable across runs.
189	func TaxonomyBlock(taxonomy Taxonomy) string {
190		var b strings.Builder
191		b.WriteString("## Taxonomy\n\n")
192		b.WriteString("Top-level categories are fixed. You may invent a new three-level path only under one of these categories:\n\n")
193	
194		categories := make([]string, 0, len(taxonomy.Categories))
195		for category := range taxonomy.Categories {
196			categories = append(categories, category)
197		}
198		sort.Strings(categories)
199		for _, category := range categories {
200			fmt.Fprintf(&b, "- `%s` — %s\n", category, taxonomy.Categories[category])
201		}
202	
203		if len(taxonomy.Paths) > 0 {
204			b.WriteString("\nKnown paths (prefer these):\n\n")
205			paths := append([]PathDef(nil), taxonomy.Paths...)
206			sort.Slice(paths, func(i, j int) bool { return paths[i].Path < paths[j].Path })
207			for _, def := range paths {
208				if def.Description != "" {
209					fmt.Fprintf(&b, "- `%s` — %s\n", def.Path, def.Description)
210				} else {
211					fmt.Fprintf(&b, "- `%s`\n", def.Path)
212				}
213			}
214		}
215		return b.String()
216	}
217	
218	// FilterPathsByTaxonomy keeps only paths whose top-level category exists in
219	// the taxonomy, recording a warning for each dropped path. Paths are already
220	// syntactically valid (factmerge.NormalizePaths ran first).
221	func FilterPathsByTaxonomy(paths []string, taxonomy Taxonomy, warnings *[]string) []string {
222		tops := TaxonomyTopLevels(taxonomy)
223		kept := paths[:0:0]
224		for _, path := range paths {
225			if _, ok := tops[TopLevel(path)]; ok {
226				kept = append(kept, path)
227				continue
228			}
229			*warnings = append(*warnings, fmt.Sprintf("dropped path under unknown category: %s", path))
230		}
231		return kept
232	}
233	
234	// ValidateKindFlag rejects an unrecognized --kind value (empty = no filter).
235	func ValidateKindFlag(kind string) error {
236		if strings.TrimSpace(kind) == "" || factmerge.ValidFactKind(kind) {
237			return nil
238		}
239		return fmt.Errorf("--kind must be one of decision|invariant|gotcha|preference|convention")
240	}
241	
242	// ValidateScopeFlag rejects an unrecognized --scope value.
243	func ValidateScopeFlag(scope string) error {
244		switch scope {
245		case "", ScopeLocal, ScopeCrossCutting:
246			return nil
247		default:
248			return fmt.Errorf("--scope must be %q or %q", ScopeLocal, ScopeCrossCutting)
249		}
250	}
251	
252	// --- manifest summary -----------------------------------------------------
253	
254	// SummarizeSource folds the flat fact store into the source manifest
255	// recorded under sources.facts in the brain manifest. Branches is left empty:
256	// memories are repo-wide, and the field survives only so older manifests
257	// still parse.
258	func SummarizeSource(now time.Time, records []factmerge.Record, chunksScanned, chunksDistilled, proposals int, warnings []string) *bmanifest.FactSource {
259		source := &bmanifest.FactSource{
260			GeneratedAt:     now,
261			TaxonomyPath:    TaxonomyPath,
262			Proposals:       proposals,
263			ChunksScanned:   chunksScanned,
264			ChunksDistilled: chunksDistilled,
265			Warnings:        append([]string(nil), warnings...),
266			ByKind:          map[string]int{},
267		}
268		for _, record := range records {
269			// A stored line carrying no id is not a fact (see IsFactRecord): it
270			// cannot be fetched, recalled, verified or superseded. Counting it
271			// here is how a damaged store re-declared its own damage as healthy
272			// on the next `remember` or `refresh`, and it is what the integrity
273			// cross-check compares against.
274			if !IsFactRecord(record) {
275				continue
276			}
277			if record.Status == factmerge.StatusCandidate {
278				// A staged candidate is not a published memory yet: counting it
279				// into Facts would inflate every surface after a crashed run,
280				// while hiding it would make the staged work invisible. Its own
281				// counter keeps both honest until the next distill reconciles it.
282				source.PendingReconcile++
283				continue
284			}
285			source.Facts++
286			switch record.Origin {
287			case OriginDistilled:
288				source.Distilled++
289			case OriginAuthored:
290				source.Authored++
291			case OriginImported:
292				// Without this bucket an imported fact raises the total and no
293				// line item, so the origins visibly do not sum to the count and
294				// nothing explains the difference.
295				source.Imported++
296			}
297			if record.Status == factmerge.StatusSuperseded {
298				source.Superseded++
299			}
300			// by_kind counts only active facts, matching what recall/tree surface
301			// (superseded/retracted facts are not retrievable), so the histogram
302			// answers "what kinds can I recall" rather than paralleling Facts.
303			if record.Status == factmerge.StatusActive {
304				source.ByKind[KindOrInferred(record)]++
305			}
306			for _, anchor := range record.Provenance {
307				if anchor.Verified {
308					source.Verified++
309				} else {
310					source.Unsigned++
311				}
312			}
313		}
314		return source
315	}
