1	package factstore
2	
3	// The repository memory store is one flat collection: facts/store.json holds
4	// every record's full payload keyed by fact id. Branch is metadata on a
5	// record, never a storage key. Schema history:
6	//
7	//	1: records + per-branch views with field overrides (unreleased)
8	//	2: bodyless marker {storage:"legacy_views"}; payloads lived in
9	//	   facts/<branch-slug>/facts.ndjson (unreleased)
10	//	3: this layout
11	//
12	// Released clients (v0.2–v0.4) predate every store schema and read/write the
13	// legacy branch NDJSON files directly — including AFTER the manifest schema
14	// bump, because their write path appends to the branch file before the
15	// manifest check fails. Load therefore folds any legacy branch files it finds
16	// (see repo_fact_compat.go), and Write parks them once their content is
17	// carried by the flat store.
18	
19	import (
20		"bytes"
21		"encoding/json"
22		"fmt"
23		"os"
24		"path/filepath"
25		"sort"
26		"strings"
27		"time"
28	
29		"github.com/entireio/entire-brain/factmerge"
30		"github.com/entireio/entire-brain/internal/cli/internal/base"
31		"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
32	)
33	
34	const RepositoryPath = "facts/store.json"
35	const repoFactsVersion = 3
36	
37	// legacyParkPrefix names the directory migration parks folded legacy branch
38	// dirs under (facts/.legacy-<unixts>/<dirname>). Verified redundant files are
39	// removed automatically; unverified bytes remain available for recovery.
40	const legacyParkPrefix = ".legacy-"
41	
42	type repoFactStore struct {
43		SchemaVersion int                        `json:"schema_version"`
44		Records       map[string]json.RawMessage `json:"records"`
45	}
46	
47	// readStoreFile reads facts/store.json raw, with the shared forward-version
48	// gate: a schema newer than this build fails closed.
49	func readStoreFile(brainDir string) (version int, data []byte, present bool, err error) {
50		if err := base.RejectSymlinkedBrainRoot(brainDir); err != nil {
51			return 0, nil, false, err
52		}
53		if err := base.RejectExistingSymlinkPathComponents(brainDir, RepositoryPath); err != nil {
54			return 0, nil, false, err
55		}
56		path := filepath.Join(brainDir, filepath.FromSlash(RepositoryPath))
57		if info, statErr := os.Lstat(path); statErr == nil && !info.Mode().IsRegular() {
58			return 0, nil, true, fmt.Errorf("repository memory store is not a regular file: %s", RepositoryPath)
59		}
60		data, readErr := os.ReadFile(path)
61		if os.IsNotExist(readErr) {
62			return 0, nil, false, nil
63		}
64		if readErr != nil {
65			return 0, nil, false, readErr
66		}
67		// A zero-byte store is a crashed writer's leftover, not a corpus: treat it
68		// as absent so readers degrade to the integrity warning instead of dying.
69		if len(bytes.TrimSpace(data)) == 0 {
70			return 0, nil, false, nil
71		}
72		version, err = brainstore.CheckedVersionedJSONHeader(data, repoFactsVersion, "repository memory store")
73		if err != nil {
74			return version, nil, true, err
75		}
76		return version, data, true, nil
77	}
78	
79	// decodeV3 decodes a schema-3 store into records keyed by id, failing closed
80	// when a body is unparseable or disagrees with its key: a key standing over a
81	// different fact's body is a substitution — the fact the key names is gone.
82	func decodeV3(data []byte) (map[string]factmerge.Record, error) {
83		var s repoFactStore
84		if _, err := brainstore.DecodeStrictVersionedJSON(data, &s, repoFactsVersion, "repository memory store"); err != nil {
85			return nil, err
86		}
87		if s.SchemaVersion != repoFactsVersion || s.Records == nil {
88			return nil, fmt.Errorf("invalid repository memory store header")
89		}
90		out := make(map[string]factmerge.Record, len(s.Records))
91		for id, raw := range s.Records {
92			var rec factmerge.Record
93			if err := json.Unmarshal(raw, &rec); err != nil {
94				return nil, fmt.Errorf("invalid repository memory record %s: %w", id, err)
95			}
96			if rec.ID != id {
97				return nil, fmt.Errorf("repository memory record %s carries id %q; the record the key names is gone — %s", id, rec.ID, RepairHint())
98			}
99			out[id] = rec
100		}
101		return out, nil
102	}
103	
104	// Load returns every stored record: the flat store plus, until migration has
105	// parked them, the legacy sources folded in memory (read-only — Load never
106	// writes). Records come back in factmerge.Sort order. Corrupt or
107	// forward-version stores fail closed.
108	func Load(brainDir string) ([]factmerge.Record, error) {
109		combined, err := loadCombined(brainDir)
110		if err != nil {
111			return nil, err
112		}
113		return combined.sorted(), nil
114	}
115	
116	// Write replaces the flat store with exactly these records. Callers hold the
117	// brain write lock over their load-mutate-write; the store lock additionally
118	// serializes snapshot commits.
119	//
120	// Legacy branch dirs still on disk are parked afterwards: under the brain
121	// write lock the caller's Load already folded their content (legacy writers
122	// take the same lock), so the written set carries everything they held — and
123	// an id the caller removed on purpose (gc, the mirror sweep) must not
124	// resurrect from a file nothing maintains anymore.
125	func Write(brainDir string, records []factmerge.Record) error {
126		return withRepoFactStoreLock(brainDir, func() error {
127			// Establish the pre-mutation migration before an intentional delete or
128			// retraction. Never merge legacy records into the caller's replacement set.
129			dirs, err := legacyBranchDirs(brainDir)
130			if err != nil {
131				return err
132			}
133			if len(dirs) > 0 {
134				if _, err := migrateRepositoryLocked(brainDir); err != nil {
135					return err
136				}
137			} else if _, _, _, err := readStoreFile(brainDir); err != nil {
138				// Preserve the forward-version gate without decoding the entire
139				// existing corpus again on every already-migrated write.
140				return err
141			}
142			_ = cleanupLegacyLocked(brainDir)
143			return writeFlatStore(brainDir, records)
144		})
145	}
146	
147	func writeFlatStore(brainDir string, records []factmerge.Record) error {
148		s := repoFactStore{SchemaVersion: repoFactsVersion, Records: make(map[string]json.RawMessage, len(records))}
149		for _, rec := range records {
150			if strings.TrimSpace(rec.ID) == "" {
151				return fmt.Errorf("refusing to store a memory without an id: %q", rec.Text)
152			}
153			raw, err := json.Marshal(rec)
154			if err != nil {
155				return err
156			}
157			s.Records[rec.ID] = raw
158		}
159		data, err := json.Marshal(s)
160		if err != nil {
161			return err
162		}
163		if err := brainstore.WriteBrainRelativeFileAtomic(brainDir, RepositoryPath, append(data, '\n'), 0o600); err != nil {
164			return err
165		}
166		return cleanupRepoFactTemps(brainDir)
167	}
168	
169	// legacyBranchDirs lists the facts/ subdirectories legacy layouts and released
170	// clients write branch NDJSON files into. Parked dirs (.legacy-*) and any
171	// other dotted name are never legacy sources.
172	func legacyBranchDirs(brainDir string) ([]string, error) {
173		if err := base.RejectExistingSymlinkPathComponents(brainDir, DirName); err != nil {
174			return nil, err
175		}
176		entries, err := os.ReadDir(filepath.Join(brainDir, DirName))
177		if os.IsNotExist(err) {
178			return nil, nil
179		}
180		if err != nil {
181			return nil, err
182		}
183		var dirs []string
184		for _, entry := range entries {
185			if !entry.IsDir() || strings.HasPrefix(entry.Name(), ".") {
186				continue
187			}
188			dirs = append(dirs, entry.Name())
189		}
190		sort.Strings(dirs)
191		return dirs, nil
192	}
193	
194	// parkLegacyDirs moves every legacy branch dir to facts/.legacy-<unixts>/.
195	// Returns the brain-relative paths it moved. Callers hold the store lock.
196	func parkLegacyDirs(brainDir string) ([]string, error) { return parkLegacyDirsVerified(brainDir, nil) }
197	
198	func parkLegacyDirsVerified(brainDir string, proofs map[string]cleanupReceipt) ([]string, error) {
199		dirs, err := legacyBranchDirs(brainDir)
200		if err != nil || len(dirs) == 0 {
201			return nil, err
202		}
203		if err := base.RejectExistingSymlinkPathComponents(brainDir, DirName); err != nil {
204			return nil, err
205		}
206		// MkdirTemp keeps repeated parks distinct: a released client can re-create
207		// a legacy dir and be parked again within the same second, and renaming
208		// onto an earlier park's entry would fail.
209		parkAbs, err := os.MkdirTemp(filepath.Join(brainDir, DirName), fmt.Sprintf("%s%d-", legacyParkPrefix, time.Now().Unix()))
210		if err != nil {
211			return nil, err
212		}
213		factsRoot, err := os.OpenRoot(filepath.Join(brainDir, DirName))
214		if err != nil {
215			return nil, err
216		}
217		defer factsRoot.Close()
218		parkRoot, err := factsRoot.OpenRoot(filepath.Base(parkAbs))
219		if err != nil {
220			return nil, err
221		}
222		defer parkRoot.Close()
223		moved := make([]string, 0, len(dirs))
224		for _, dir := range dirs {
225			rel := filepath.Join(DirName, dir)
226			if err := base.RejectExistingSymlinkPathComponents(brainDir, rel); err != nil {
227				return moved, err
228			}
229			if err := factsRoot.Rename(dir, filepath.Join(filepath.Base(parkAbs), dir)); err != nil {
230				return moved, err
231			}
232			// Persist both sides of the move before a receipt or a later mutation
233			// can authorize removal. Otherwise a power loss could restore an active
234			// legacy path and revive a memory the caller deliberately deleted.
235			if err := brainstore.SyncPinnedDirectory(parkRoot); err != nil {
236				return moved, err
237			}
238			if err := brainstore.SyncPinnedDirectory(factsRoot); err != nil {
239				return moved, err
240			}
241			if err := cleanupCheckpoint("parked"); err != nil {
242				return moved, err
243			}
244			// A receipt ties the input consumed by the verified migration to its
245			// committed result. Later deliberate deletions must not strand this copy.
246			if proof, ok := proofs[dir]; ok {
247				branch, openErr := parkRoot.OpenRoot(dir)
248				if openErr == nil {
249					encoded, _ := json.Marshal(proof)
250					// A failed receipt only defers cleanup; the committed migration remains
251					// valid and the original recovery bytes remain parked.
252					_ = writeCleanupReceipt(branch, append(encoded, '\n'))
253					branch.Close()
254				}
255			}
256			moved = append(moved, filepath.ToSlash(rel))
257		}
258		return moved, nil
259	}
260	
261	func withRepoFactStoreLock(brainDir string, fn func() error) error {
262		if err := base.RejectSymlinkedBrainRoot(brainDir); err != nil {
263			return err
264		}
265		rel := filepath.Join(brainstore.BrainLockDirName, "memory-store.lock")
266		if err := base.RejectExistingSymlinkPathComponents(brainDir, rel); err != nil {
267			return err
268		}
269		lock, err := brainstore.AcquireFileLock(filepath.Join(brainDir, rel), "memory_store_locked", brainstore.BrainWriteLockTimeout)
270		if err != nil {
271			return err
272		}
273		defer lock.Close()
274		return fn()
275	}
276	
277	// A process can die while the atomic writer is filling its temporary file.
278	// These are never exportable data or backups; writes remove them even when the
279	// live snapshot no longer references the memory. Production callers hold the
280	// store lock, so no live writer is swept.
281	func cleanupRepoFactTemps(brainDir string) error {
282		if err := base.RejectExistingSymlinkPathComponents(brainDir, DirName); err != nil {
283			return err
284		}
285		entries, err := os.ReadDir(filepath.Join(brainDir, DirName))
286		if os.IsNotExist(err) {
287			return nil
288		}
289		if err != nil {
290			return err
291		}
292		for _, entry := range entries {
293			if !strings.HasPrefix(entry.Name(), ".store.json.tmp-") {
294				continue
295			}
296			rel := filepath.Join(DirName, entry.Name())
297			if err := base.RejectExistingSymlinkPathComponents(brainDir, rel); err != nil {
298				return err
299			}
300			info, err := entry.Info()
301			if err != nil {
302				return err
303			}
304			if !info.Mode().IsRegular() {
305				return fmt.Errorf("nonregular memory store temporary file: %s", rel)
306			}
307			if err := os.Remove(filepath.Join(brainDir, rel)); err != nil {
308				return err
309			}
310		}
311		return nil
312	}
