94	// --- taxonomy -------------------------------------------------------------
95	
96	// DefaultTaxonomy is the shipped baseline taxonomy. The top-level
97	// categories here are fixed in Phase A; distillation may invent a new
98	// three-level path only under one of these categories. The brain regenerates
99	// taxonomy.json from this default on refresh.
100	func DefaultTaxonomy(now time.Time) Taxonomy {
101		return Taxonomy{
102			GeneratedAt: now,
103			Categories: map[string]string{
104				"preferences":  "How the user wants to work and how code should be written.",
105				"architecture": "Resolved design, boundary, and data-flow decisions and their rationale.",
106				"project":      "Stack, tooling, CI/CD, ownership, and standing project facts.",
107				"workflow":     "Branching, testing, review, and release process rules.",
108				"constraints":  "Non-obvious invariants, gotchas, and hard constraints.",
109			},
110			Paths: []PathDef{
111				{Path: "preferences.coding.style", Description: "Stated code-style preferences.", Examples: []string{"prefers table-driven tests"}},
112				{Path: "preferences.workflow.general", Description: "How the user prefers to work day to day."},
113				{Path: "architecture.boundaries.rationale", Description: "Why a module or package boundary exists."},
114				{Path: "architecture.data.flow", Description: "How data moves through the system."},
115				{Path: "project.tooling.stack", Description: "Languages, frameworks, and tools the project uses."},
116				{Path: "project.ci_cd.pipeline", Description: "Build, test, and deploy pipeline facts."},
117				{Path: "workflow.branching.rules", Description: "Branching and merge conventions."},
118				{Path: "workflow.testing.rules", Description: "How and when tests must be run."},
119				{Path: "constraints.invariants.general", Description: "Invariants that must hold across changes."},
120			},
