143	// WriteTaxonomy persists the active taxonomy snapshot.
144	func WriteTaxonomy(brainDir string, taxonomy Taxonomy) error {
145		data, err := json.MarshalIndent(taxonomy, "", "  ")
146		if err != nil {
147			return err
148		}
149		data = append(data, '\n')
150		return brainstore.WriteBrainRelativeFileAtomic(brainDir, TaxonomyPath, data, 0o600)
151	}
