164	// SortedTaxonomyTopLevels returns the taxonomy's top-level categories sorted
165	// alphabetically, for stable user-facing messages (e.g. rejecting an explicit
166	// --path under an unknown category).
167	func SortedTaxonomyTopLevels(taxonomy Taxonomy) []string {
168		cats := make([]string, 0, len(taxonomy.Categories))
169		for category := range taxonomy.Categories {
170			cats = append(cats, category)
171		}
172		sort.Strings(cats)
173		return cats
174	}
