176	// PathKnownTopLevel reports whether path's top-level category exists in the
177	// taxonomy. This is the conservative drift check: a fact keeps its assigned
178	// paths literally, and only its top-level category must still exist for it to
179	// remain valid.
180	func PathKnownTopLevel(taxonomy Taxonomy, path string) bool {
181		_, ok := TaxonomyTopLevels(taxonomy)[TopLevel(path)]
182		return ok
183	}
184	
185	// TaxonomyBlock renders the taxonomy as the prompt section the agent uses to
186	// classify facts: the fixed top-level categories and the known three-level
187	// paths with descriptions. Output is deterministic (sorted) so the rendered
188	// prompt is stable across runs.
189	func TaxonomyBlock(taxonomy Taxonomy) string {
190		var b strings.Builder
191		b.WriteString("## Taxonomy\n\n")
192		b.WriteString("Top-level categories are fixed. You may invent a new three-level path only under one of these categories:\n\n")
193	
194		categories := make([]string, 0, len(taxonomy.Categories))
195		for category := range taxonomy.Categories {
196			categories = append(categories, category)
197		}
198		sort.Strings(categories)
199		for _, category := range categories {
200			fmt.Fprintf(&b, "- `%s` — %s\n", category, taxonomy.Categories[category])
201		}
202	
203		if len(taxonomy.Paths) > 0 {
204			b.WriteString("\nKnown paths (prefer these):\n\n")
205			paths := append([]PathDef(nil), taxonomy.Paths...)
206			sort.Slice(paths, func(i, j int) bool { return paths[i].Path < paths[j].Path })
207			for _, def := range paths {
208				if def.Description != "" {
209					fmt.Fprintf(&b, "- `%s` — %s\n", def.Path, def.Description)
210				} else {
211					fmt.Fprintf(&b, "- `%s`\n", def.Path)
212				}
213			}
214		}
215		return b.String()
216	}
