218	// FilterPathsByTaxonomy keeps only paths whose top-level category exists in
219	// the taxonomy, recording a warning for each dropped path. Paths are already
220	// syntactically valid (factmerge.NormalizePaths ran first).
221	func FilterPathsByTaxonomy(paths []string, taxonomy Taxonomy, warnings *[]string) []string {
222		tops := TaxonomyTopLevels(taxonomy)
223		kept := paths[:0:0]
224		for _, path := range paths {
225			if _, ok := tops[TopLevel(path)]; ok {
226				kept = append(kept, path)
227				continue
228			}
229			*warnings = append(*warnings, fmt.Sprintf("dropped path under unknown category: %s", path))
230		}
231		return kept
232	}
