235	func ValidateKindFlag(kind string) error {
236		if strings.TrimSpace(kind) == "" || factmerge.ValidFactKind(kind) {
237			return nil
238		}
239		return fmt.Errorf("--kind must be one of decision|invariant|gotcha|preference|convention")
240	}
