252	// --- manifest summary -----------------------------------------------------
253	
254	// SummarizeSource folds the flat fact store into the source manifest
255	// recorded under sources.facts in the brain manifest. Branches is left empty:
256	// memories are repo-wide, and the field survives only so older manifests
257	// still parse.
258	func SummarizeSource(now time.Time, records []factmerge.Record, chunksScanned, chunksDistilled, proposals int, warnings []string) *bmanifest.FactSource {
259		source := &bmanifest.FactSource{
260			GeneratedAt:     now,
261			TaxonomyPath:    TaxonomyPath,
262			Proposals:       proposals,
263			ChunksScanned:   chunksScanned,
264			ChunksDistilled: chunksDistilled,
265			Warnings:        append([]string(nil), warnings...),
266			ByKind:          map[string]int{},
267		}
268		for _, record := range records {
269			// A stored line carrying no id is not a fact (see IsFactRecord): it
270			// cannot be fetched, recalled, verified or superseded. Counting it
271			// here is how a damaged store re-declared its own damage as healthy
272			// on the next `remember` or `refresh`, and it is what the integrity
273			// cross-check compares against.
274			if !IsFactRecord(record) {
275				continue
276			}
277			if record.Status == factmerge.StatusCandidate {
278				// A staged candidate is not a published memory yet: counting it
279				// into Facts would inflate every surface after a crashed run,
280				// while hiding it would make the staged work invisible. Its own
281				// counter keeps both honest until the next distill reconciles it.
282				source.PendingReconcile++
283				continue
284			}
285			source.Facts++
286			switch record.Origin {
287			case OriginDistilled:
288				source.Distilled++
289			case OriginAuthored:
290				source.Authored++
291			case OriginImported:
292				// Without this bucket an imported fact raises the total and no
293				// line item, so the origins visibly do not sum to the count and
294				// nothing explains the difference.
295				source.Imported++
296			}
297			if record.Status == factmerge.StatusSuperseded {
298				source.Superseded++
299			}
300			// by_kind counts only active facts, matching what recall/tree surface
301			// (superseded/retracted facts are not retrievable), so the histogram
302			// answers "what kinds can I recall" rather than paralleling Facts.
303			if record.Status == factmerge.StatusActive {
304				source.ByKind[KindOrInferred(record)]++
305			}
306			for _, anchor := range record.Provenance {
307				if anchor.Verified {
308					source.Verified++
309				} else {
310					source.Unsigned++
311				}
312			}
313		}
314		return source
315	}
