79	// decodeV3 decodes a schema-3 store into records keyed by id, failing closed
80	// when a body is unparseable or disagrees with its key: a key standing over a
81	// different fact's body is a substitution — the fact the key names is gone.
82	func decodeV3(data []byte) (map[string]factmerge.Record, error) {
83		var s repoFactStore
84		if _, err := brainstore.DecodeStrictVersionedJSON(data, &s, repoFactsVersion, "repository memory store"); err != nil {
85			return nil, err
86		}
87		if s.SchemaVersion != repoFactsVersion || s.Records == nil {
88			return nil, fmt.Errorf("invalid repository memory store header")
89		}
90		out := make(map[string]factmerge.Record, len(s.Records))
91		for id, raw := range s.Records {
92			var rec factmerge.Record
93			if err := json.Unmarshal(raw, &rec); err != nil {
94				return nil, fmt.Errorf("invalid repository memory record %s: %w", id, err)
95			}
96			if rec.ID != id {
97				return nil, fmt.Errorf("repository memory record %s carries id %q; the record the key names is gone — %s", id, rec.ID, RepairHint())
98			}
99			out[id] = rec
100		}
101		return out, nil
102	}
