100	// factPlainTokens lowercases and splits on non-alphanumerics (underscore
101	// kept), the tokenization the retrieval eval measured.
102	func factPlainTokens(text string) []string {
103		lower := strings.ToLower(text)
104		return strings.FieldsFunc(lower, func(r rune) bool {
105			return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '_')
106		})
107	}
