109	// factQueryTerms are the deduplicated query tokens, with the history stopword
110	// list applied so "how does the" carries no weight. Like factSearchTokens on
111	// the document side, the query unions the ASCII plain tokens with the
112	// Unicode-aware normalizer's tokens: the plain tokenizer alone yields nothing
113	// for CJK/Cyrillic queries and truncates accented words at the accent.
114	func factQueryTerms(query string) []string {
115		seen := map[string]struct{}{}
116		var terms []string
117		add := func(t string) {
118			if len(t) < 2 || brainstore.QueryStopword(t) {
119				return
120			}
121			if _, ok := seen[t]; ok {
122				return
123			}
124			seen[t] = struct{}{}
125			terms = append(terms, t)
126		}
127		for _, t := range factPlainTokens(query) {
128			add(t)
129		}
130		for _, t := range strings.Fields(normalizeHistorySearchText(query)) {
131			for _, piece := range expandCJKBigrams(t) {
132				add(piece)
133			}
134		}
135		return terms
136	}
137	
138	// bm25Corpus holds the per-call corpus statistics BM25 needs. Recomputed per
139	// query over the candidate set — ponytail: O(corpus) per query, measured at
140	// well under a millisecond for 1,209 facts; an inverted index is the upgrade
141	// path if fact counts grow by orders of magnitude.
142	type bm25Corpus struct {
143		docTokens [][]string
144		df        map[string]int
145		avgLen    float64
146	}
147	
148	func newBM25Corpus(facts []factRecord) bm25Corpus {
149		c := bm25Corpus{
150			docTokens: make([][]string, len(facts)),
151			df:        make(map[string]int, len(facts)*8),
152		}
153		total := 0
154		for i, f := range facts {
155			tokens := factSearchTokens(f)
156			c.docTokens[i] = tokens
157			total += len(tokens)
158			seen := make(map[string]struct{}, len(tokens))
159			for _, t := range tokens {
160				if _, ok := seen[t]; ok {
161					continue
162				}
163				seen[t] = struct{}{}
164				c.df[t]++
165			}
166		}
167		if len(facts) > 0 {
168			c.avgLen = float64(total) / float64(len(facts))
169		}
170		return c
171	}
172	
173	// bm25Score is the Okapi BM25 text relevance of candidate i for the query
174	// terms, over this corpus.
175	func (c bm25Corpus) bm25Score(i int, terms []string) float64 {
176		tokens := c.docTokens[i]
177		if len(tokens) == 0 || len(terms) == 0 {
178			return 0
179		}
180		tf := make(map[string]int, len(tokens))
181		for _, t := range tokens {
182			tf[t]++
183		}
184		n := float64(len(c.docTokens))
185		score := 0.0
186		for _, term := range terms {
187			f := float64(tf[term])
188			if f == 0 {
189				continue
190			}
191			idf := math.Log((n-float64(c.df[term])+0.5)/(float64(c.df[term])+0.5) + 1)
192			norm := 1 - bm25B + bm25B*float64(len(tokens))/c.avgLen
193			score += idf * f * (bm25K1 + 1) / (f + bm25K1*norm)
194		}
195		return score
196	}
197	
198	// factBM25Score is the full facts ranking score: BM25 text relevance plus the
199	// two previously measured boosts (shared code locus, closed-negative kind).
200	// Boosts apply only to facts that already match, so neither creates a match on
201	// its own — same contract as the scorer this replaces.
202	func factBM25Score(f factRecord, c bm25Corpus, i int, terms []string, queryLocus []string) float64 {
203		score := c.bm25Score(i, terms)
204		if score <= 0 {
205			return 0
206		}
207		if overlap := factstore.LocusOverlapTokens(queryLocus, base.FactLocusOf(f)); overlap > 0 {
208			score += float64(overlap) * bm25LocusBoost
209		}
210		if factstore.KindOrInferred(f) == factKindClosedNegative {
211			score += bm25ClosedNegativeBoost
212		}
213		return score
214	}
