216	// filterFacts narrows candidates by taxonomy path prefix, fact kind, and
217	// minimum update time. Zero values skip that filter. A path prefix matches a
218	// whole segment boundary: "architecture.sync" matches "architecture.sync" and
219	// "architecture.sync.auth", not "architecture.syncextra".
220	func filterFacts(facts []factRecord, pathPrefix, kind string, since time.Time) []factRecord {
221		if pathPrefix == "" && kind == "" && since.IsZero() {
222			return facts
223		}
224		out := make([]factRecord, 0, len(facts))
225		for _, f := range facts {
226			if kind != "" && f.Kind != kind {
227				continue
228			}
229			if !since.IsZero() && f.UpdatedAt.Before(since) {
230				continue
231			}
232			if pathPrefix != "" && !factMatchesPathPrefix(f, pathPrefix) {
233				continue
234			}
235			out = append(out, f)
236		}
237		return out
238	}
239	
240	func factMatchesPathPrefix(f factRecord, prefix string) bool {
241		for _, p := range f.Paths {
242			if p == prefix || strings.HasPrefix(p, prefix+".") {
243				return true
244			}
245		}
246		return false
247	}
