14	// BM25 replaces the flat term-overlap text score on the facts path. The flat
15	// scorer collapses at corpus scale: common terms match hundreds of facts and
16	// the discriminative rare term no longer decides the ordering. BM25's IDF
17	// weighting fixes exactly that, and the 2026-10 retrieval eval (eval ledger;
18	// trail #278) measured it matching or beating the semantic fusion arm across
19	// models and corpus sizes, which is why the embedder was removed.
20	const (
21		bm25K1 = 1.2
22		bm25B  = 0.75
23	
24		// Boost scales re-expressed for the BM25 range (one strong rare-term hit
25		// contributes roughly idf ~= 4-7). The old int scorer weighted a locus
26		// token at 6x a term hit and closed-negative at 3x; these keep those
27		// proportions.
28		bm25LocusBoost          = 8.0
29		bm25ClosedNegativeBoost = 4.0
