32	// factSearchTokens are the indexable tokens of one fact: its text plus its
33	// taxonomy paths (dots split so "architecture.sync.auth" matches "sync").
34	// Facts index BOTH plain lowercase tokens ("mysql") and the camel-split form
35	// the history normalizer produces ("my sql"), so a query matches whichever
36	// shape the asker types. The plain form is what the shipped-decision eval
37	// measured (trail #278); the camel-split additions only widen reachability.
38	func factSearchTokens(f factRecord) []string {
39		haystack := f.Text + " " + strings.ReplaceAll(strings.Join(f.Paths, " "), ".", " ")
40		tokens := factPlainTokens(haystack)
41		seen := make(map[string]struct{}, len(tokens)*2)
42		for _, t := range tokens {
43			seen[t] = struct{}{}
44		}
