46			for _, piece := range expandCJKBigrams(t) {
47				if _, ok := seen[piece]; ok {
48					continue
49				}
50				seen[piece] = struct{}{}
51				tokens = append(tokens, piece)
52			}
53		}
54		return tokens
55	}
