57	// expandCJKBigrams splits a normalized token into word pieces for scripts
58	// written without spaces: runs of Han/Kana/Hangul become character bigrams
59	// (the standard CJK analyzer trick), everything else passes through whole.
60	// Without this a CJK query tokenizes to one long run that never equals the
61	// fact's equally long run, and matching silently returns nothing — the old
62	// substring scorer handled CJK for free, so BM25 must too.
63	func expandCJKBigrams(token string) []string {
64		runes := []rune(token)
65		var out []string
66		var plain []rune
67		flushPlain := func() {
68			if len(plain) > 0 {
69				out = append(out, string(plain))
70				plain = plain[:0]
71			}
72		}
73		for i := 0; i < len(runes); {
74			if !isCJKRune(runes[i]) {
75				plain = append(plain, runes[i])
76				i++
77				continue
78			}
79			flushPlain()
80			j := i
81			for j < len(runes) && isCJKRune(runes[j]) {
82				j++
83			}
84			if j-i == 1 {
85				out = append(out, string(runes[i:j]))
86			}
87			for k := i; k+1 < j; k++ {
88				out = append(out, string(runes[k:k+2]))
89			}
90			i = j
91		}
92		flushPlain()
93		return out
94	}
