38	// resolveFactsTarget resolves the repo, brain directory, and the branch facts
39	// are scoped to (the live git branch unless overridden). It is shared by the
40	// fact read/write commands.
41	func resolveFactsTarget(ctx context.Context, opts Options, target, branchOverride string) (repoDir, brainDir, branch string, err error) {
42		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
43		if err != nil {
44			return "", "", "", err
45		}
46		if !local {
47			return "", "", "", fmt.Errorf("memories require a local repository path: %s", target)
48		}
49		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
50		if err != nil {
51			return "", "", "", err
52		}
53		branch = strings.TrimSpace(branchOverride)
54		if branch == "" {
55			if current, gitErr := base.GitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
56				branch = strings.TrimSpace(current)
57			}
58		}
59		if branch == "" {
