1	package cli
2	
3	import (
4		"sort"
5		"strings"
6	
7		"github.com/entireio/entire-brain/internal/cli/internal/base"
8		"github.com/entireio/entire-brain/internal/cli/internal/factstore"
9	)
10	
11	// factLocusBoost is added per shared code identifier between the query and a
12	// fact (see factstore.LocusOverlap) — a strong, high-precision signal.
13	const factLocusBoost = 60
14	
15	// factClosedNegativeBoost lifts a closed-negative fact above similarly-matching
16	// peers: when the query touches a settled-dead-end's territory, the "this was
17	// tried and failed" entry is the highest-value thing the brain can surface (it
18	// prevents re-exploration, not just re-derivation). Applied only when the fact
19	// already matched (score > 0), so kind alone never creates a match — and no
20	// pre-existing fact carries the kind, so measured baselines are unchanged
21	// until distill/reclassify produce closed-negatives.
22	const factClosedNegativeBoost = 30
23	
24	// factLexicalScore is the legacy integer scorer: term/substring score, locus
25	// boost, and the closed-negative kind boost. rankFacts moved to BM25
26	// (facts_bm25.go); the post-failure hook still uses this scorer for its
27	// threshold semantics (hookPostFailureMinScore is calibrated to this scale).
28	func factLexicalScore(f factRecord, query string, queryLocus []string) int {
29		score := factQueryScore(f, query)
30		if overlap := factstore.LocusOverlapTokens(queryLocus, base.FactLocusOf(f)); overlap > 0 {
31			score += overlap * factLocusBoost
32		}
33		if score > 0 && factstore.KindOrInferred(f) == factKindClosedNegative {
34			score += factClosedNegativeBoost
35		}
36		return score
37	}
38	
39	// scoredFact pairs a fact with its query score for ranking.
40	type scoredFact struct {
41		Record factRecord
42		Score  float64
43	}
44	
45	// rankFacts scores facts against a query and returns the top matches, highest
46	// score first with most-recently-updated as the tiebreak. Superseded and
47	// retracted facts are excluded unless includeAll is set. An empty query returns
48	// the most recent facts (no scoring), which makes `recall ""` a useful "what do
49	// you know about this branch" listing.
50	func rankFacts(facts []factRecord, query string, limit int, includeAll bool) []factRecord {
51		if limit <= 0 {
52			limit = 10
53		}
54		candidates := make([]factRecord, 0, len(facts))
55		for _, f := range facts {
56			if !includeAll && f.Status != factStatusActive {
57				continue
58			}
59			candidates = append(candidates, f)
60		}
61	
62		if strings.TrimSpace(query) == "" {
63			sort.SliceStable(candidates, func(i, j int) bool {
64				return candidates[i].UpdatedAt.After(candidates[j].UpdatedAt)
65			})
66			if len(candidates) > limit {
67				candidates = candidates[:limit]
68			}
69			return candidates
70		}
71	
72		queryLocus := base.FactLocus(query)
73		terms := factQueryTerms(query)
74		corpus := newBM25Corpus(candidates)
75		scored := make([]scoredFact, 0, len(candidates))
76		for i, f := range candidates {
77			if score := factBM25Score(f, corpus, i, terms, queryLocus); score > 0 {
78				scored = append(scored, scoredFact{Record: f, Score: score})
79			}
80		}
81		sort.SliceStable(scored, func(i, j int) bool {
82			if scored[i].Score != scored[j].Score {
83				return scored[i].Score > scored[j].Score
84			}
85			return scored[i].Record.UpdatedAt.After(scored[j].Record.UpdatedAt)
86		})
87		if len(scored) > limit {
88			scored = scored[:limit]
89		}
90		out := make([]factRecord, len(scored))
91		for i, s := range scored {
92			out[i] = s.Record
93		}
94		return out
95	}
96	
97	// factQueryScore scores a fact against a query, reusing the history index's
98	// term-matching machinery so facts and history rank consistently. The score
99	// combines a whole-query substring match, per-term overlap, and a bonus when a
100	// term hits a taxonomy path (a path match is a strong topical signal).
101	func factQueryScore(record factRecord, query string) int {
102		haystack := record.Text + " " + strings.Join(record.Paths, " ")
103		score := 0
104		if historyTextMatchesQuery(haystack, query) {
105			score += 200
106		}
107		terms := historyQueryTerms(query)
108		if len(terms) == 0 {
109			return score
110		}
111		normalizedText := normalizeHistorySearchText(haystack)
112		normalizedPaths := normalizeHistorySearchText(strings.Join(record.Paths, " "))
113		matches := 0
114		for _, term := range terms {
115			if strings.Contains(normalizedText, term) {
116				matches++
117				score += 10
118				if strings.Contains(normalizedPaths, term) {
119					score += 8
120				}
121			}
122		}
123		if matches == 0 && score < 200 {
124			return 0
125		}
126		if matches == len(terms) {
127			score += 20 // all query terms present
128		}
129		return score
