43	// first so repeated evals are deterministic and cheap.
44	func expandQuery(ctx context.Context, run base.DistillAgentRunner, args []string, repoDir, query string, cache *expansionCache) (string, error) {
45		if v, ok := cache.get(query); ok {
46			return v, nil
47		}
48		out, err := run(ctx, repoDir, args, []byte(query), defaultDistillTimeout)
49		if err != nil {
50			return "", err
51		}
52		exp := parseExpansion(out)
53		cache.set(query, exp)
54		return exp, nil
55	}
56	
