526		// token-free, so it is part of the normal refresh — the user never has to
527		// discover a second build command. Rebuilt when sessions changed or --force.
528		manifest, _ = bmanifest.Load(brainDir)
529		if !refreshOpts.skipSessions && manifest != nil && manifest.Sources != nil && manifest.Sources.Sessions != nil {
530			finishPatterns := progress.Step("pattern layer")
531			if _, err := refreshPatternLayerContext(ctx, brainDir, refreshOpts.force, opts.Now().UTC()); err != nil {
532				finishPatterns(err)
533				if reportStageAndShouldAbort(brainComponentPatterns, err) {
534					return err
535				}
536			} else {
537				// The internal pattern corpus is a rebuildable cache; a corpus failure must
538				// not break the rest of the brain, so it is a warning here (the explicit
539				// `patterns refresh` is the stricter surface that fails on corpus errors).
540				if cerr := buildPatternCorpus(brainDir, opts.Now().UTC(), patternCorpusGraphContext{Context: ctx, Options: opts, RepoDir: repoDir, Binary: refreshOpts.graphBinary}); cerr != nil {
541					fmt.Fprintf(cmd.ErrOrStderr(), "warning: pattern corpus: %v\n", cerr)
542				}
543				finishPatterns(nil)
544				reportStageAndShouldAbort(brainComponentPatterns, nil)
545			}
546		}
547		// Include the intentional semantic skip beside the success line.
548		if refreshOpts.semanticWorktreeSkip {
549			printAroundLiveLine(cmd.OutOrStdout(), "%s\n", refreshWorktreeSemanticSkipNote(base.SetupCommandPrefix(os.LookupEnv)))
550		}
551		if !refreshOpts.skipTranscriptSweep {
552			maintainFactsStorage(ctx, cmd.ErrOrStderr(), opts, brainDir)
553		}
