555		webhook.NotifyBrainWebhook(ctx, cmd.ErrOrStderr(), opts, webhook.WebhookBrainRefreshed, opts.Now())
556		printAroundLiveLine(cmd.OutOrStdout(), "refreshed brain: %s\n", brainDir)
557		if refreshOpts.statusAfter && !outputExplicit {
558			statusCmd := &cobra.Command{Use: "status"}
559			statusCmd.SetOut(cmd.OutOrStdout())
560			statusCmd.SetErr(cmd.ErrOrStderr())
561			if err := runAgentStatus(ctx, statusCmd, opts, agentStatusOptions{}, repoDir); err != nil {
562				return fmt.Errorf("status after refresh: %w", err)
563			}
564		}
