569	// projector reads is actually there. See the call site in runRefresh.

func seedNeededForBrain(manifest *exportManifest) bool {
	// Seed freshness is independent of checkpoint/session availability: a
	// refresh may intentionally omit sessions, so an empty session list is no
	// seed-missing signal (it rebuilt an otherwise current seed every time).
	return manifest == nil || manifest.Sources == nil || manifest.Sources.Seed == nil
}

func seedRefreshNeeded(ctx context.Context, opts Options, repoDir string, manifest *exportManifest, worktree bool) (bool, error) {
	if seedNeededForBrain(manifest) {
		return true, nil
	}
	seed := manifest.Sources.Seed
	head, err := base.GitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD")
	if err != nil {
		return false, nameDegenerateRepoFailure(ctx, opts.Runner, repoDir, fmt.Errorf("resolve HEAD for repository context refresh: %w", err))
	}
	if seed.Commit != head {
		return true, nil
	}
	if worktree {
		hash, err := worktreeFingerprint(ctx, opts.Runner, repoDir)
		if err != nil {
			return false, nameDegenerateRepoFailure(ctx, opts.Runner, repoDir, fmt.Errorf("fingerprint worktree for repository context refresh: %w", err))
		}
		return seed.WorktreeMode != "worktree" || seed.WorktreeHash != hash, nil
	}
	return seed.WorktreeMode == "worktree", nil
}

